/// <summary>
/// PricingAttribute of table <c>CustTable</c> field CustGroup.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Customer, GUPPricingAttributeSourceLevel::Header)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(CustTable, CustGroup))]
internal class GUPPricingAttributeCustTableCustGroup extends GUPPricingAttributeCustTable implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(CustTable, CustGroup);
}

public Set getAllowedValuesWithDescription()
{
    var ret = new Set(Types::AnyType);

    CustTable custTable;
    CustGroup custGroup;

    while select custGroup from custtable
        group by custGroup
        join custGroup
        group by CustGroup, Name
        where custTable.CustGroup == custGroup.custGroup
    {
        GUPPricingAttributeAllowedValuesObject valueObject =
            new GUPPricingAttributeAllowedValuesObject(custGroup.custGroup, custGroup.Name);
        ret.add(valueObject);
    }

    return ret;
}
